<?php defined('_JEXEC') or die;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Router\Route; ?><div class="container-fluid"><h1>Tour and Holiday Packages</h1><div class="row g-3 mb-4"><?php foreach($this->stats as $k=>$v): ?><div class="col-6 col-lg-3"><div class="card"><div class="card-body"><div class="text-muted"><?php echo ucfirst(str_replace('_',' ',$k)); ?></div><strong class="fs-3"><?php echo $v; ?></strong></div></div></div><?php endforeach; ?></div><div class="card mb-4"><div class="card-body"><h2 class="h4">Add package</h2><form method="post" enctype="multipart/form-data" action="<?php echo Route::_('index.php?option=com_kaarbooking&task=packages.save'); ?>" class="row g-3"><div class="col-md-4"><input class="form-control" name="title" required placeholder="Package title"></div><div class="col-md-2"><input class="form-control" type="number" min="1" name="duration_days" value="1" title="Days"></div><div class="col-md-2"><input class="form-control" type="number" min="0" name="duration_nights" value="0" title="Nights"></div><div class="col-md-2"><select class="form-select" name="booking_mode"><option value="whole_vehicle">Whole vehicle</option><option value="per_seat">Per seat</option><option value="wedding_event">Wedding/event</option></select></div><div class="col-md-2"><select class="form-select" name="vehicle_type_id"><option value="">Any vehicle type</option><?php foreach($this->types as $t): ?><option value="<?php echo $t['id']; ?>"><?php echo htmlspecialchars($t['title'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><input class="form-control" type="number" min="1" name="capacity" placeholder="Capacity"></div><div class="col-md-2"><input class="form-control" type="number" min="0" step=".01" name="base_price" placeholder="Base price"></div><div class="col-md-1"><input class="form-control" name="currency" value="INR" maxlength="3"></div><div class="col-md-5"><input class="form-control" name="summary" placeholder="Short summary"></div><div class="col-md-6"><textarea class="form-control" name="description" placeholder="Description"></textarea></div><div class="col-md-6"><textarea class="form-control" name="inclusions" placeholder="One included item per line"></textarea></div><div class="col-md-4"><label class="form-label">Package images (2–4)</label><input class="form-control" type="file" name="package_images[]" accept="image/jpeg,image/png,image/webp" multiple required></div><div class="col-md-2"><label><input type="checkbox" name="state" value="1" checked> Published</label></div><div class="col-md-2"><button class="btn btn-primary">Add package</button></div><?php echo HTMLHelper::_('form.token'); ?></form></div></div><form method="get" class="row g-2 mb-3"><input type="hidden" name="option" value="com_kaarbooking"><input type="hidden" name="view" value="packages"><div class="col-md-3"><input class="form-control" name="filter_search" value="<?php echo htmlspecialchars($this->filters['search'],ENT_QUOTES,'UTF-8'); ?>" placeholder="Package title"></div><div class="col-md-2"><select class="form-select" name="filter_mode"><option value="">All booking modes</option><option>whole_vehicle</option><option>per_seat</option><option>wedding_event</option></select></div><div class="col-md-2"><select class="form-select" name="filter_state"><option value="">All states</option><option value="1">Published</option><option value="0">Unpublished</option></select></div><div class="col-md-2"><button class="btn btn-secondary">Filter</button></div></form><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Image</th><th>Title</th><th>Duration</th><th>Mode</th><th>Vehicle</th><th>Capacity</th><th>Price</th><th>State</th></tr></thead><tbody><?php foreach($this->items as $i): ?><tr><td><?php if(!empty($i['image_path'])): ?><img src="<?php echo htmlspecialchars(\Joomla\CMS\Uri\Uri::root().$i['image_path'],ENT_QUOTES,'UTF-8'); ?>" alt="" width="64" height="48" style="object-fit:cover" loading="lazy"><?php endif; ?></td><td><?php echo htmlspecialchars($i['title'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo $i['duration_days']; ?>d / <?php echo $i['duration_nights']; ?>n</td><td><?php echo $i['booking_mode']; ?></td><td><?php echo htmlspecialchars($i['vehicle_type']??'Any',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo (int)$i['capacity']; ?></td><td><?php echo htmlspecialchars($i['currency'].' '.number_format((float)$i['base_price'],2),ENT_QUOTES,'UTF-8'); ?></td><td><?php echo $i['state']?'Published':'Unpublished'; ?></td></tr><?php endforeach; ?><?php if(!$this->items): ?><tr><td colspan="8">No packages match the filters.</td></tr><?php endif; ?></tbody></table></div></div>




